// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 val, uint256 lockTime, uint256 amount, uint256 deposit) public {
        // Bind inputs to realistic ranges
        val = bound(val, 0, type(uint256).max / 2);
        lockTime = bound(lockTime, 0, 1e6);
        amount = bound(amount, 0, type(uint256).max / 2);
        deposit = bound(deposit, 0, type(uint256).max / 2 - 1e18);

        // Drive the contract: set MinSum, initialize, put some funds, then call Collect
        vm.assume(val < type(uint256).max); // ensure no overflow in later additions
        c.SetMinSum(val);
        c.SetLogFile(address(new LogFile()));
        c.Initialized();

        // Put enough msg.value so balance >= MinSum
        vm.deal(address(this), deposit + 1 ether);
        (bool putOk,) = address(c).call{value: deposit}("");
        require(putOk, "Put failed");

        // Warp time to pass unlock
        vm.warp(block.timestamp + lockTime + 1);

        // Call Collect with amount
        (bool collectOk,) = address(c).call(abi.encodeWithSelector(c.Collect.selector, amount));

        // Assert: MinSum equals the value originally set (val), not val+1
        assertTrue(c.MinSum() == val);
    }
}

contract LogFile {
    struct Message {
        address Sender;
        string  Data;
        uint Val;
        uint  Time;
    }
    Message[] public History;
    Message LastMsg;
    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}

